-- Bento · seed · transit graph: the Kansai–Sanyo corridor and Tokyo
-- Generated by scripts/export-transit-seed.ts from src/lib/transit/seed/kansai-sanyo.ts and tokyo.ts.
-- Do not edit by hand; edit the TypeScript and re-export.

on conflict (id) do update set name = excluded.name, name_ja = excluded.name_ja, city_id = excluded.city_id, coords = excluded.coords, lines = excluded.lines;

on conflict (from_station, to_station, line) do update set mode = excluded.mode, operator = excluded.operator, km = excluded.km, minutes = excluded.minutes, fare_jpy = excluded.fare_jpy, stops = excluded.stops, note = excluded.note;
